using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "BossCustomButtonDescriptionData", menuName = "Data/UIDescriptionData/BossCustomButtonDescriptionData", order = 0)]
public class BossCustomButtonDescriptionData : CustomButtonDescriptionData
{
	private const string bossRewardDescriptionID = "BossRewardDescription";

	[SerializeField]
	private int starShardsAmount;

	public override string GetLocalizedDescription(string id)
	{
		string localizedString = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("BossRewardDescription");
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(id) + "\n" + Smart.Format(localizedString, starShardsAmount);
	}
}
